#!/usr/bin/env bashset -euo pipefailROOT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"BACKEND_DIR="$ROOT_DIR/Backend/payment-processing-system"FRONTEND_DIR="$ROOT_DIR/Frontend"if [[ ! -d "$BACKEND_DIR" ]]; then  echo "Backend directory not found: $BACKEND_DIR" >&2  exit 1fiif [[ ! -f "$FRONTEND_DIR/package.json" ]]; then  echo "Frontend package.json not found: $FRONTEND_DIR/package.json" >&2  exit 1fiif command -v lsof >/dev/null 2>&1; then  PORT_PID="$(lsof -ti:8082 || true)"  if [[ -n "$PORT_PID" ]]; then    echo "Stopping process on :8082 (PID $PORT_PID)..."    kill -9 "$PORT_PID" || true  fifistart_backend() {  echo "Starting backend on http://localhost:8082 ..."  if [[ -f "$BACKEND_DIR/mvnw" ]]; then    (      cd "$BACKEND_DIR"      chmod +x ./mvnw      nohup ./mvnw -f "$BACKEND_DIR/pom.xml" spring-boot:run > "$ROOT_DIR/backend.log" 2>&1 &      echo $! > "$ROOT_DIR/.backend.pid"    )  elif [[ -f "$BACKEND_DIR/mvnw.cmd" ]]; then    (      cd "$BACKEND_DIR"      nohup cmd.exe /c mvnw.cmd -f "$BACKEND_DIR/pom.xml" spring-boot:run > "$ROOT_DIR/backend.log" 2>&1 &      echo $! > "$ROOT_DIR/.backend.pid"    )  else    echo "No Maven wrapper found in backend directory." >&2    exit 1  fi}start_backendecho "Installing frontend dependencies..."cd "$FRONTEND_DIR"npm installecho "Starting frontend dev server..."npm run dev